<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\{ActivityLog,Appointment};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class AppointmentController extends Controller {
    private function rules($partial=false){$p=$partial?'sometimes':'required';return ['patient_id'=>"$p|exists:patients,id",'doctor_id'=>"$p|exists:doctors,id",'appointment_date'=>"$p|date",'start_time'=>"$p|date_format:H:i",'end_time'=>"$p|date_format:H:i|after:start_time",'reason'=>"$p|string|max:255",'status'=>'sometimes|in:Scheduled,Checked In,In Progress,Completed,Cancelled,No Show','notes'=>'nullable|string|max:2000'];}
    private function permitted(Request $r,$q){if($r->user()->role==='doctor'){$id=optional($r->user()->doctor)->id;$q->where('doctor_id',$id ?: 0);}return $q;}
    private function conflict($data,$ignore=null){if(in_array($data['status']??'Scheduled',['Cancelled','No Show']))return false;return Appointment::where('doctor_id',$data['doctor_id'])->whereDate('appointment_date',$data['appointment_date'])->whereNotIn('status',['Cancelled','No Show'])->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->where('start_time','<',$data['end_time'])->where('end_time','>',$data['start_time'])->exists();}
    public function index(Request $r){$q=$this->permitted($r,Appointment::with(['patient:id,patient_number,full_name,phone','doctor:id,name,specialisation']));foreach(['doctor_id','patient_id','status'] as $f)if($r->$f)$q->where($f,$r->$f);if($r->date)$q->whereDate('appointment_date',$r->date);return response()->json($q->orderByDesc('appointment_date')->orderBy('start_time')->paginate(max(1,min((int) $r->input('per_page',10),50))));}
    public function store(Request $r){if($r->user()->role==='doctor')abort(403);$data=$r->validate($this->rules());if($this->conflict($data))throw ValidationException::withMessages(['start_time'=>['This doctor already has an overlapping appointment.']]);$a=DB::transaction(function()use($data,$r){$data['created_by']=$r->user()->id;$a=Appointment::create($data);ActivityLog::record($r->user(),'create',$a,"Created appointment #{$a->id}.");return $a;});return response()->json(['data'=>$a->load('patient','doctor'),'message'=>'Appointment created successfully.'],201);}
    public function show(Request $r,Appointment $appointment){$this->permitted($r,Appointment::whereKey($appointment))->firstOrFail();return response()->json(['data'=>$appointment->load('patient','doctor','creator:id,name')]);}
    public function update(Request $r,Appointment $appointment){$this->permitted($r,Appointment::whereKey($appointment))->firstOrFail();$data=$r->validate($this->rules(true));if($r->user()->role==='doctor')$data=array_intersect_key($data,array_flip(['status','notes']));$merged=array_merge($appointment->only(['doctor_id','appointment_date','start_time','end_time','status']),$data);if($this->conflict($merged,$appointment->id))throw ValidationException::withMessages(['start_time'=>['This doctor already has an overlapping appointment.']]);$appointment->update($data);ActivityLog::record($r->user(),'update',$appointment,"Updated appointment #{$appointment->id}.");return response()->json(['data'=>$appointment->load('patient','doctor'),'message'=>'Appointment updated successfully.']);}
    public function destroy(Request $r,Appointment $appointment){if($r->user()->role==='doctor')abort(403);$appointment->update(['status'=>'Cancelled']);ActivityLog::record($r->user(),'cancel',$appointment,"Cancelled appointment #{$appointment->id}.");return response()->json(['data'=>$appointment,'message'=>'Appointment cancelled successfully.']);}
}
